package com.smartmanager.nativeapp;
import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
/** Shared native tabbed manager for Hotspot, PPPoE and User Manager. */
public final class ManagementActivity extends Activity {
 private LinearLayout page,tabs;private ListView list;private EditText search;private TextView status;private String section,tab="users";private List<Map<String,String>> rows=new ArrayList<>();private final ArrayList<Map<String,String>> visibleRows=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean writing;private final int NAVY=Color.rgb(22,47,80),BLUE=Color.rgb(23,103,177),TEAL=Color.rgb(22,166,166);
 @Override public void onCreate(Bundle b){super.onCreate(b);section=getIntent().getStringExtra("section");if(section==null)section="hotspot";build();load();}
 private void build(){ScrollView shell=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(16,18,16,30);page.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);page.setBackgroundColor(Color.rgb(237,244,250));shell.addView(page);setContentView(shell);TextView title=text(titleFor(),23,true);page.addView(title);status=text("جاري التحميل...",14,false);page.addView(status);tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);page.addView(tabs);String[] names={"users","profiles","active"};String[] labels={"المستخدمون","الباقات","الجلسات النشطة"};for(int i=0;i<3;i++){final String n=names[i];Button b=button(labels[i],BLUE);b.setOnClickListener(v->{tab=n;load();});tabs.addView(b,new LinearLayout.LayoutParams(0,-2,1));}search=new EditText(this);search.setHint("بحث بالاسم أو الحالة");search.setSingleLine(true);page.addView(search);list=new ListView(this);page.addView(list,new LinearLayout.LayoutParams(-1,520));Button refresh=button("تحديث",TEAL);refresh.setOnClickListener(v->load());page.addView(refresh);if(!section.equals("usermanager")){Button add=button("إضافة حساب",BLUE);add.setOnClickListener(v->createDialog());page.addView(add);}search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(android.text.Editable e){}});}
 private void load(){status.setText("جاري قراءة "+label()+"...");worker.execute(()->{try{SecureConnectionStore sec=new SecureConnectionStore(this);try(RouterService r=connect(sec)){List<Map<String,String>> result;if(section.equals("hotspot")){HotspotService s=new HotspotService(r);result=tab.equals("profiles")?s.profiles():tab.equals("active")?s.active():s.users();}else if(section.equals("pppoe")){PppoeService s=new PppoeService(r);result=tab.equals("profiles")?s.profiles():tab.equals("active")?s.active():s.secrets();}else{String v=version(r);UserManagerService s=new UserManagerService(r);result=tab.equals("profiles")?s.profiles(v):tab.equals("active")?s.sessions(v):s.users(v);}rows=result;ui(()->{status.setText(rows.isEmpty()?"لا توجد بيانات":"تم تحميل "+rows.size()+" عنصرًا");render();});}}catch(Exception e){ui(()->{status.setText("فشل التحميل: "+safe(e));rows=new ArrayList<>();render();});}});}
 private void render(){ArrayList<String> out=new ArrayList<>();visibleRows.clear();String q=search==null?"":search.getText().toString().trim().toLowerCase(Locale.ROOT);for(Map<String,String> m:rows){String s=display(m);if(q.isEmpty()||s.toLowerCase(Locale.ROOT).contains(q)){visibleRows.add(m);out.add(s);}}if(out.isEmpty())out.add("لا توجد نتائج مطابقة");list.setOnItemClickListener((parent,view,pos,id)->{if(pos<visibleRows.size()){Map<String,String> m=visibleRows.get(pos);Intent i=new Intent(this,ResourceDetailActivity.class);i.putExtra("section",section);i.putExtra("kind",tab);i.putExtra("id",m.get(".id"));i.putExtra("name",m.getOrDefault("name",m.getOrDefault("user",m.getOrDefault("username",""))));i.putExtra("profile",m.getOrDefault("profile",m.getOrDefault("service","")));startActivity(i);}});list.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_list_item_2,android.R.id.text1,out){@Override public View getView(int p,View v,android.view.ViewGroup parent){View x=super.getView(p,v,parent);((TextView)x.findViewById(android.R.id.text1)).setTextColor(NAVY);return x;}});}
 private String display(Map<String,String> m){String name=m.getOrDefault("name",m.getOrDefault("user",m.getOrDefault("username","غير مسمى")));String profile=m.getOrDefault("profile",m.getOrDefault("service",m.getOrDefault("address","")));String state="true".equalsIgnoreCase(m.get("disabled"))?"معطل":"فعال";String id=m.getOrDefault(".id","");return name+(profile.isEmpty()?"":"\nالباقة/العنوان: "+profile)+"\nالحالة: "+state+(id.isEmpty()?"":"  | id: "+id);}
 private void createDialog(){if(writing){status.setText("عملية جارية");return;}LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);EditText n=field("الاسم",p),pw=field("كلمة المرور",p),pr=field("اسم الباقة",p);new AlertDialog.Builder(this).setTitle("إضافة حساب").setView(p).setNegativeButton("إلغاء",null).setPositiveButton("تنفيذ",(d,w)->create(n.getText().toString().trim(),pw.getText().toString(),pr.getText().toString().trim())).show();}
 private void create(String n,String pw,String pr){if(n.isEmpty()||pw.isEmpty()||pr.isEmpty()){status.setText("كل الحقول مطلوبة");return;}writing=true;worker.execute(()->{try{SecureConnectionStore ignored=new SecureConnectionStore(this);try(RouterService r=connect(ignored)){if(section.equals("hotspot"))new HotspotService(r).addUser(n,pw,pr);else new PppoeService(r).addSecret(n,pw,pr);ui(()->{writing=false;status.setText("تمت الإضافة");load();});}}catch(Exception e){ui(()->{writing=false;status.setText("فشل أو نتيجة غير مؤكدة: "+safe(e));});}});}
 private EditText field(String h,LinearLayout p){EditText e=new EditText(this);e.setHint(h);e.setSingleLine(true);p.addView(e);return e;}private RouterService connect(SecureConnectionStore s)throws Exception{android.content.SharedPreferences p=getSharedPreferences("router_connection",MODE_PRIVATE);String pw=s.get();RouterService r=new RouterService(p.getString("host",""),Integer.parseInt(p.getString("port","8728")),p.getBoolean("tls",false));r.login(p.getString("user",""),pw==null?"":pw);return r;}private String version(RouterService r)throws Exception{List<Map<String,String>> x=r.execute("/system/resource/print","=.proplist=version");return x.isEmpty()?"":x.get(0).getOrDefault("version","");}private String titleFor(){return section.equals("hotspot")?"Hotspot":section.equals("pppoe")?"PPPoE":"User Manager";}private String label(){return tab.equals("profiles")?"الباقات":tab.equals("active")?"الجلسات":"المستخدمين";}private String safe(Exception e){return e.getMessage()==null?"خطأ غير معروف":e.getMessage();}private TextView text(String s,int z,boolean b){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(NAVY);t.setPadding(8,10,8,10);if(b)t.setTypeface(null,Typeface.BOLD);return t;}private Button button(String s,int c){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(c));return b;}private void ui(Runnable r){runOnUiThread(r);}@Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
